import { fileURLToPath } from "node:url";
import { defineConfig } from "vitest/config";
import vue from "@vitejs/plugin-vue";

// The Vue plugin is needed so component tests can import `.vue` SFCs directly;
// the pure-utility tests do not depend on it. `#nuxt-charts` is generated by
// the module at build time, so tests point it at a configurable stand-in.
export default defineConfig({
  plugins: [vue()],
  resolve: {
    alias: {
      "#nuxt-charts": fileURLToPath(new URL("./test/fixtures/nuxt-charts.ts", import.meta.url)),
    },
  },
  test: {
    environment: "happy-dom",
    include: ["test/**/*.test.ts"],
  },
});
